1	// The constructor keeps public named params (`remoteDataSource`,
2	// `accessTokenProvider`) distinct from the private fields they initialize,
3	// matching `auth_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:async';
6	
7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../../../../core/network/access_token_provider.dart';
11	import '../../../../core/session/session_expiry_notifier.dart';
12	import '../../domain/entities/session_status.dart';
13	import '../../domain/repositories/session_repository.dart';
14	import '../datasources/auth_remote_data_source.dart';
15	
16	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
17	/// [restoreSession] is unconditional — no client-side expiry math — and
18	/// covers the I/O matrix (spec-1-4):
19	/// - no stored refresh token -> no network call, emits `unauthenticated`
20	///   immediately.
21	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
22	///   emits `authenticated`.
23	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
24	///   token) -> `clearSession`, emits `unauthenticated`.
25	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
26	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
27	///   retries naturally.
28	class SessionRepositoryImpl implements SessionRepository {
29	  SessionRepositoryImpl({
30	    required AuthRemoteDataSource remoteDataSource,
31	    required AccessTokenProvider accessTokenProvider,
32	    required SessionExpiryNotifier sessionExpiryNotifier,
33	  }) : _remoteDataSource = remoteDataSource,
34	       _accessTokenProvider = accessTokenProvider,
35	       _sessionExpiryNotifier = sessionExpiryNotifier {
36	    // Story 1.5 — the one bridge from `core`'s expiry signal onto this
37	    // feature's own `SessionStatus` stream (Design Notes). Subscribed for
38	    // this repository's whole lifetime; cancelled in [dispose].
39	    _expirySubscription = _sessionExpiryNotifier.expiredEvents.listen(
40	      (_) => _onSessionExpired(),
41	      // Mirrors `statusStream`'s own internal subscription a few lines
42	      // below: no current `SessionExpiryNotifier` implementation ever
43	      // errors, but without this, a future one that did would surface as
44	      // an unhandled zone exception instead of just being dropped here.
45	      onError: (_, _) {},
46	    );
47	  }
48	
49	  final AuthRemoteDataSource _remoteDataSource;
50	  final AccessTokenProvider _accessTokenProvider;
51	  final SessionExpiryNotifier _sessionExpiryNotifier;
52	  late final StreamSubscription<void> _expirySubscription;
53	  final StreamController<SessionStatus> _statusController =
54	      StreamController<SessionStatus>.broadcast();
55	
56	  /// The last status emitted, so a consumer that subscribes *after* the
57	  /// first emission (a later `StreamBuilder`, or Story 1.5/1.6's own
58	  /// listener) still sees current state immediately rather than nothing
59	  /// until the next change — see [statusStream].
60	  SessionStatus? _lastStatus;
61	
62	  @override
63	  SessionStatus? get currentStatus => _lastStatus;
64	
65	  @override
66	  void markAuthenticated() => _emit(SessionStatus.authenticated);
67	
68	  @override
69	  Stream<SessionStatus> get statusStream {
70	    // `Stream.multi` runs this callback once per listener (and, with
71	    // `isBroadcast: true`, supports more than one simultaneously) — each
72	    // new listener synchronously gets the cached last status (if any)
73	    // before being attached to the live broadcast controller for whatever
74	    // comes next. This is this story's whole reason to not just expose
75	    // `_statusController.stream` directly: a plain broadcast stream only
76	    // ever delivers *future* events to a listener that joins late.
77	    return Stream<SessionStatus>.multi((controller) {
78	      final last = _lastStatus;
79	      if (last != null) {
80	        controller.add(last);
81	      }
82	      final subscription = _statusController.stream.listen(
83	        controller.add,
84	        onError: controller.addError,
85	        onDone: controller.close,
86	      );
87	      controller.onCancel = subscription.cancel;
88	    }, isBroadcast: true);
89	  }
90	
91	  void _emit(SessionStatus status) {
92	    // Guards against `dispose()` (wired to `get_it`'s `sl.reset()`) racing
93	    // an in-flight `restoreSession()` call — without this, a late `.add()`
94	    // after `.close()` would throw an unhandled `StateError` instead of
95	    // just being a no-op on an already-torn-down repository.
96	    if (_statusController.isClosed) {
97	      return;
98	    }
99	    _lastStatus = status;
100	    _statusController.add(status);
101	  }
102	
103	  /// "Always" boundary — a mid-session expiry only ever matters while the
104	  /// user is currently [SessionStatus.authenticated]; any other current
105	  /// status (not yet decided at boot, already unauthenticated/logged out,
106	  /// or already [SessionStatus.expired] from an earlier event) is a
107	  /// silent no-op — covers both the "expiry while not authenticated"
108	  /// post-logout race and the "already-open overlay" double-event case in
109	  /// the I/O matrix (a second event here never re-emits once [_lastStatus]
110	  /// is already [SessionStatus.expired]).
111	  void _onSessionExpired() {
112	    if (_lastStatus == SessionStatus.authenticated) {
113	      _emit(SessionStatus.expired);
114	    }
115	  }
116	
117	  @override
118	  Future<Either<Failure, Unit>> restoreSession() async {
119	    String? refreshToken;
120	    try {
121	      refreshToken = await _accessTokenProvider.readRefreshToken();
122	    } catch (error) {
123	      // A thrown platform exception from the native secure-storage channel
124	      // must never escape unmapped (RNF09) — fail closed, same as any other
125	      // unreadable session.
126	      _emit(SessionStatus.unauthenticated);
127	      return left(Failure.malformedResponse(message: error.toString()));
128	    }
129	
130	    if (refreshToken == null || refreshToken.isEmpty) {
131	      // Fresh install / post-logout (null), or a stored-but-empty token
132	      // (the backend response schema has no `minLength` on `refreshToken`,
133	      // so an empty string is a theoretically valid stored value) — either
134	      // way, no network call: `auth-refresh`'s own request schema requires
135	      // `minLength: 1`, so an empty token would only fail server-side.
136	      _emit(SessionStatus.unauthenticated);
137	      return left(
138	        const Failure.authExpired(message: 'No stored session to restore'),
139	      );
140	    }
141	
142	    final result = await _remoteDataSource.refresh(refreshToken);
143	    return result.match(
144	      (failure) async {
145	        // Only a backend-confirmed dead token clears storage; any other
146	        // failure (offline, timeout, malformed response, ...) leaves it
147	        // untouched so the next boot retries naturally.
148	        if (failure is AuthExpired || failure is AuthInvalid) {
149	          try {
150	            await _accessTokenProvider.clearSession();
151	          } catch (_) {
152	            // Best-effort clear — the session is already being treated as
153	            // unauthenticated below regardless of whether this succeeds.
154	          }
155	        }
156	        _emit(SessionStatus.unauthenticated);
157	        return left(failure);
158	      },
159	      (session) async {
160	        try {
161	          await _accessTokenProvider.saveSession(
162	            accessToken: session.accessToken,
163	            refreshToken: session.refreshToken,
164	          );
165	        } catch (error) {
166	          _emit(SessionStatus.unauthenticated);
167	          return left(Failure.malformedResponse(message: error.toString()));
168	        }
169	        _emit(SessionStatus.authenticated);
170	        return right(unit);
171	      },
172	    );
173	  }
174	
175	  @override
176	  Future<void> dispose() async {
177	    await _expirySubscription.cancel();
178	    await _statusController.close();
179	  }
180	}
