1	import 'package:dio/dio.dart';
2	import 'package:flutter_dotenv/flutter_dotenv.dart';
3	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
4	import 'package:get_it/get_it.dart';
5	
6	import '../../features/auth/auth_injection.dart';
7	import '../network/access_token_provider.dart';
8	import '../network/api_client.dart';
9	import '../network/header_interceptor.dart';
10	import '../network/retry_interceptor.dart';
11	import '../network/url_builder.dart';
12	import '../session/session_expiry_notifier.dart';
13	
14	/// The project's single `get_it` instance — exactly one DI container exists
15	/// (architecture spine). Every feature's `registerXFeature()` registers
16	/// through this same `sl`, never a second container.
17	final sl = GetIt.instance;
18	
19	/// Bootstraps core infrastructure: loads `.env`, then registers
20	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
21	/// interceptors) and `ApiClient` through `sl` — the `dio` +
22	/// `flutter_secure_storage` + `get_it` integration spike this story proves
23	/// before anything else is built on top of it.
24	Future<void> setupCoreDependencies() async {
25	  await dotenv.load(fileName: '.env');
26	
27	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
28	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
29	
30	  sl.registerLazySingleton<FlutterSecureStorage>(
31	    () => const FlutterSecureStorage(),
32	  );
33	
34	  sl.registerLazySingleton<AccessTokenProvider>(
35	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
36	  );
37	
38	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
39	
40	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
41	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
42	  // own registration below. Registration order here is cosmetic, not
43	  // load-bearing: `registerLazySingleton` only builds its instance on first
44	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
45	  // correctly regardless of which of the two is registered first.
46	  sl.registerLazySingleton<SessionExpiryNotifier>(
47	    () => SessionExpiryNotifierImpl(),
48	    dispose: (notifier) => notifier.dispose(),
49	  );
50	
51	  sl.registerLazySingleton<Dio>(() {
52	    final dio = Dio(
53	      BaseOptions(
54	        // Design note (docs/input is silent on exact numbers): a stalled
55	        // connection must still fail instead of hanging indefinitely.
56	        connectTimeout: const Duration(seconds: 10),
57	        receiveTimeout: const Duration(seconds: 30),
58	        sendTimeout: const Duration(seconds: 30),
59	      ),
60	    );
61	    dio.interceptors.add(
62	      HeaderInterceptor(
63	        anonKey: supabaseAnonKey,
64	        accessTokenProvider: sl<AccessTokenProvider>(),
65	      ),
66	    );
67	    dio.interceptors.add(RetryInterceptor(dio));
68	    return dio;
69	  });
70	
71	  sl.registerLazySingleton<ApiClient>(
72	    () => ApiClient(
73	      dio: sl<Dio>(),
74	      urlBuilder: sl<UrlBuilder>(),
75	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
76	    ),
77	  );
78	
79	  registerAuthFeature();
80	}
81	
82	/// Test/teardown helper — resets the single `get_it` instance so each test
83	/// bootstraps its own clean registrations.
84	Future<void> resetCoreDependencies() => sl.reset();
85

1	import '../../core/di/injection_container.dart';
2	import '../../core/network/access_token_provider.dart';
3	import '../../core/session/session_expiry_notifier.dart';
4	import 'data/datasources/auth_remote_data_source.dart';
5	import 'data/repositories/auth_repository_impl.dart';
6	import 'data/repositories/session_repository_impl.dart';
7	import 'domain/repositories/auth_repository.dart';
8	import 'domain/repositories/session_repository.dart';
9	import 'presentation/cubit/auth_cubit.dart';
10	
11	/// Registers the `auth` feature into the project's single `get_it` instance
12	/// (`sl`). Called from `setupCoreDependencies()` once core infrastructure is
13	/// up, since this feature only needs `ApiClient`/`AccessTokenProvider`,
14	/// already registered there.
15	void registerAuthFeature() {
16	  sl.registerLazySingleton<AuthRemoteDataSource>(
17	    () => AuthRemoteDataSource(sl()),
18	  );
19	
20	  sl.registerLazySingleton<AuthRepository>(
21	    () => AuthRepositoryImpl(
22	      remoteDataSource: sl(),
23	      accessTokenProvider: sl<AccessTokenProvider>(),
24	    ),
25	  );
26	
27	  // The epic's ONE new DI-singleton access point for session validity (AD) —
28	  // registered as a singleton so every consumer (`main.dart` here; Story
29	  // 1.5's overlay and Story 1.6's `go_router` redirect later) shares the
30	  // same `statusStream`, not a fresh instance each. `dispose:` wires
31	  // `SessionRepository.dispose()` into `get_it`'s own reset lifecycle, so
32	  // `resetCoreDependencies()` (`sl.reset()`) closes its `StreamController`
33	  // instead of leaking one on every test teardown.
34	  sl.registerLazySingleton<SessionRepository>(
35	    () => SessionRepositoryImpl(
36	      remoteDataSource: sl(),
37	      accessTokenProvider: sl<AccessTokenProvider>(),
38	      sessionExpiryNotifier: sl<SessionExpiryNotifier>(),
39	    ),
40	    dispose: (repository) => repository.dispose(),
41	  );
42	
43	  // Story 1.6 — `AuthCubit` additionally depends on `SessionRepository`
44	  // (registered above) so its `submit()` success branch can call
45	  // `markAuthenticated()`.
