109	  const secureStorageChannel = MethodChannel(
110	    'plugins.it_nomads.com/flutter_secure_storage',
111	  );
112	  final fakeNativeStorage = <String, String>{};
113	
114	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
115	    final args = call.arguments as Map<dynamic, dynamic>;
116	    switch (call.method) {
117	      case 'write':
118	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
119	        return null;
120	      case 'read':
121	        return fakeNativeStorage[args['key'] as String];
122	      case 'delete':
123	        fakeNativeStorage.remove(args['key'] as String);
124	        return null;
125	      case 'containsKey':
126	        return fakeNativeStorage.containsKey(args['key'] as String);
127	      default:
128	        return null;
129	    }
130	  }
