132	  setUp(() async {
133	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
134	        .setMockMethodCallHandler(
135	          secureStorageChannel,
136	          handleSecureStorageCall,
137	        );
138	    await resetCoreDependencies();
139	    await setupCoreDependencies();
140	    // `ConfirmationDialog.isOpen` is a static single-overlay guard (shared
141	    // across every instance by design, Story 1.5) — reset it so one test's
142	    // unclosed dialog never leaks into the next.
143	    ConfirmationDialog.isOpen = false;
144	  });
145	
146	  tearDown(() async {
147	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
148	        .setMockMethodCallHandler(secureStorageChannel, null);
